import{_ as r}from"./chunks/login.6CBtYGVc.js";import{_ as a,a as n}from"./chunks/payment.CXzQaLTe.js";import{_ as s,C as i,o as h,c as l,a2 as e,E as d}from"./chunks/framework.DSc8fo6x.js";const y=JSON.parse('{"title":"Cashier quick guide","description":"","frontmatter":{"pageClass":"print-compact"},"headers":[],"relativePath":"en/kassir.md","filePath":"en/kassir.md"}'),g={name:"en/kassir.md"};function c(p,t,u,m,_,b){const o=i("KVideo");return h(),l("div",null,[t[0]||(t[0]=e('<h1 id="cashier-quick-guide" tabindex="-1">Cashier quick guide <a class="header-anchor" href="#cashier-quick-guide" aria-label="Permalink to &quot;Cashier quick guide&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Print this page and keep it next to the till</p><p>The <a href="./pdf.html">Download PDF</a> page has the &quot;Cashier quick guide&quot; — one A4 sheet.</p></div><h2 id="_1-opening-the-program" tabindex="-1">1. Opening the program <a class="header-anchor" href="#_1-opening-the-program" aria-label="Permalink to &quot;1. Opening the program&quot;">​</a></h2><p>Green <strong>Kassa</strong> icon on the desktop → <strong>choose your name</strong> → <strong>password</strong> → <strong>Log in</strong>.</p><p><img src="'+r+'" alt="Login screen"></p><h2 id="_2-selling" tabindex="-1">2. Selling <a class="header-anchor" href="#_2-selling" aria-label="Permalink to &quot;2. Selling&quot;">​</a></h2><ol><li><strong>Scan the product&#39;s barcode</strong> — the product goes into the cart (a &quot;beep&quot;). Scan the same product again and the quantity goes up.</li><li>No barcode? <strong>Type the name</strong> in the box at the top and choose it from the list.</li><li>Products sold by weight (kg) — enter the weight, e.g. <code>0.750</code>.</li><li>Change the quantity: <strong>−</strong> / <strong>+</strong>. Remove a wrong product with <strong>✕</strong>.</li></ol><p><img src="'+a+'" alt="Sale screen"></p>',8)),d(o,{name:"satis"}),t[1]||(t[1]=e('<h2 id="_3-payment" tabindex="-1">3. Payment <a class="header-anchor" href="#_3-payment" aria-label="Permalink to &quot;3. Payment&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Button</th><th>When</th></tr></thead><tbody><tr><td><strong>Cash</strong> or <strong>F2</strong></td><td>Enter the money the customer gave you (or press 5 ₼, 10 ₼…). The program shows the <strong>change due</strong>. If the amount is exact, leave it empty.</td></tr><tr><td><strong>Card</strong> or <strong>F3</strong></td><td>First check that the payment went through on the bank terminal, then confirm.</td></tr></tbody></table><p>Then <strong>Complete sale</strong> or <strong>Enter</strong>.</p><p><img src="'+n+'" alt="Cash payment"></p><h2 id="_4-receipt" tabindex="-1">4. Receipt <a class="header-anchor" href="#_4-receipt" aria-label="Permalink to &quot;4. Receipt&quot;">​</a></h2><ul><li>If a receipt printer is connected, the receipt <strong>prints by itself</strong>.</li><li>If not, press the <strong>&quot;Receipt&quot;</strong> button in the green message after the sale.</li></ul><h2 id="_5-sounds" tabindex="-1">5. Sounds <a class="header-anchor" href="#_5-sounds" aria-label="Permalink to &quot;5. Sounds&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sound</th><th>Meaning</th></tr></thead><tbody><tr><td>Short &quot;beep&quot;</td><td>Product found</td></tr><tr><td>Low tone</td><td>Product not found — the <strong>admin</strong> must add the product to the system</td></tr></tbody></table><h2 id="_6-closing" tabindex="-1">6. Closing <a class="header-anchor" href="#_6-closing" aria-label="Permalink to &quot;6. Closing&quot;">​</a></h2><p>The <strong>✕</strong> in the top right corner of the window. The program makes a backup and closes. If nobody touches it for a while, the program logs you out — enter your password again.</p><h2 id="if-something-goes-wrong" tabindex="-1">If something goes wrong <a class="header-anchor" href="#if-something-goes-wrong" aria-label="Permalink to &quot;If something goes wrong&quot;">​</a></h2><ul><li>Blank white screen / &quot;error&quot; — <strong>Reload</strong>, or close the window and open it again. Sales are not lost.</li><li>Forgot your password — the <strong>admin</strong> sets a new one in &quot;Users&quot;.</li><li>Anything else — <a href="./problemler.html">If something goes wrong</a>.</li></ul>',12))])}const w=s(g,[["render",c]]);export{y as __pageData,w as default};
